// Runs the generated apps-script/Code.js the way Google does: one global script with
// SpreadsheetApp, LockService and ScriptApp provided as globals.
import { describe, it, expect, beforeAll } from 'vitest';
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import vm from 'node:vm';
import { FakeSheet, FakeSpreadsheet, fakeServices } from './fakes.js';
import { HEADERS, formRow } from './helpers.js';

let code;
beforeAll(() => {
  execFileSync('node', ['scripts/build-gas.mjs']);
  code = readFileSync('apps-script/Code.js', 'utf8');
});

function load() {
  const orders = new FakeSheet('Form Responses 1', [[...HEADERS, 'Paid?'], [...formRow({ name: 'Bundle Test' }), false]]);
  const ss = new FakeSpreadsheet([orders]);
  const services = fakeServices(ss);
  const toasts = [];
  const alerts = [];
  services.SpreadsheetApp.getActive = () => ({ toast: (m) => toasts.push(m) });
  const ui = services.SpreadsheetApp.getUi;
  services.SpreadsheetApp.getUi = () => ({ ...ui(), alert: (m) => alerts.push(m) });
  const context = vm.createContext({ ...services, Intl, Date, console });
  vm.runInContext(code, context);
  return { context, orders, services, toasts, alerts };
}

describe('the Apps Script bundle', () => {
  it('defines the functions Google calls and they work', () => {
    const { context, orders, services, toasts, alerts } = load();
    for (const fn of ['onOpen', 'onEdit', 'onFormSubmitTrigger', 'dailyRefresh', 'refreshNow', 'setupBreadClub']) {
      expect(typeof context[fn]).toBe('function');
    }
    context.setupBreadClub();
    expect(alerts[0]).toMatch(/^Bread Club is set up\. Added columns: Money went to/);
    const status = orders.grid[0].indexOf('Status');
    expect(orders.grid[1][status]).toBe('Unpaid');
    context.onFormSubmitTrigger();
    context.dailyRefresh();
    context.refreshNow();
    expect(toasts).toEqual(['Bread Club: refreshed']);
    context.onOpen();
    expect(services.menus[0].title).toBe('Bread Club');
    context.setupBreadClub();
    expect(alerts[1]).toBe('Bread Club is set up.');
  });

  it('is marked as generated', () => {
    expect(code.startsWith('// GENERATED by `npm run build`')).toBe(true);
  });
});
